:host {
  --ink: #1a202c;
  --muted: #718096;
  --accent: #2C5282;
  --warm: #dd6b20;
  --line: #e2e8f0;
  --paper: #F7FAFC;
  --bg-canvas: #ffffff;
  --font-base: 16px;
  --font-small: 14px;
}

.chapter-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  max-width: 1000px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--line);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 1.75rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--accent);
}

.chapter-summary {
  font-size: var(--font-base);
  color: var(--muted);
  margin: 0;
}

.interaction-area {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  margin-bottom: 2rem;
  background: var(--bg-canvas);
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.chart-wrapper {
  position: relative;
  width: 100%;
  height: 500px;
  background: var(--bg-canvas);
}

svg {
  width: 100%;
  height: 100%;
  display: block;
}

.controls-area {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.stepper-container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
}

.control-btn {
  background: var(--accent);
  color: white;
  border: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  font-size: 1.2rem;
  cursor: pointer;
  transition: background 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.control-btn:hover {
  background: #1a365d;
}

.control-btn:disabled {
  background: var(--line);
  cursor: not-allowed;
}

.step-indicators {
  display: flex;
  gap: 0.5rem;
}

.indicator {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--line);
  transition: background 0.3s;
}

.indicator.active {
  background: var(--accent);
  transform: scale(1.2);
}

.step-content {
  background: var(--paper);
  padding: 1rem;
  border-left: 4px solid var(--accent);
  border-radius: 0 4px 4px 0;
}

.step-content h3 {
  margin: 0 0 0.5rem 0;
  font-size: 1.1rem;
  color: var(--ink);
}

.step-content p {
  margin: 0 0 1rem 0;
  font-size: var(--font-small);
  color: var(--muted);
}

.source-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.8rem;
  cursor: pointer;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(44, 82, 130, 0.05);
}

.reset-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: var(--font-small);
  align-self: flex-start;
  transition: all 0.2s;
}

.reset-btn:hover {
  border-color: var(--warm);
  color: var(--warm);
}

.data-table-container {
  background: var(--bg-canvas);
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.data-table-container h3 {
  margin: 0 0 1rem 0;
  font-size: 1.2rem;
  color: var(--ink);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--font-small);
}

.data-table th,
.data-table td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

.data-table th {
  background: var(--paper);
  font-weight: 600;
  color: var(--ink);
}

.data-table tr:hover {
  background: rgba(44, 82, 130, 0.03);
}

.table-note {
  margin: 1rem 0 0 0;
  font-size: 0.85rem;
  color: var(--muted);
  font-style: italic;
}

@media (max-width: 768px) {
  .interaction-area {
    grid-template-columns: 1fr;
  }

  .chart-wrapper {
    height: 400px;
  }

  .controls-area {
    order: -1;
  }
}
