(function() {
  'use strict';

  // 教学假设：基于 Figure 9 及文本描述构建的简化模型
  const TEACHING_ASSUMPTIONS = [
    "图表基于 Figure 9 的视觉证据及第 16 页文本描述构建，非原始训练数据。",
    "'Always Treated'组在第 2 个月达到 2.5 次/小时，第 5 个月超过 3.0 次/小时。",
    "'Never Treated'组在第 8-10 个月达到 2.5 次/小时，增长缓慢。",
    "'Treated 5 mo.'组前 5 个月轨迹与'Never Treated'组重合，第 5 个月后迅速追赶。",
    "Y 轴范围设为 1-4 次/小时，X 轴为 0-10 个月，符合原文描述范围。"
  ];

  // 局限说明
  const LIMITATIONS = [
    "样本在 5 个月后截断，因为超过 5 个月的处理后观测值较少（见脚注 15），限制了对长期效应的推断。",
    "无法区分代理是真正'学会'了技能，还是仅仅在机械地遵循 AI 的建议（作者避免使用'学习曲线'一词）。",
    "不同入职队列的代理在潜在能力上没有系统性差异的假设可能不完全成立。",
    "图表为教学示例，展示趋势而非精确统计拟合，具体数值参考原文表格。"
  ];

  // 步骤数据
  const STEPS = [
    {
      title: "阶段一：自然成长期 (0-5 个月)",
      text: "所有新代理（无论未来是否获得 AI）在入职初期都遵循相同的缓慢成长轨迹。生产力从约 2.0 次/小时起步，依靠自然经验积累缓慢提升。此时，'晚获得 AI 组'与'从未获得 AI 组'的曲线完全重合。",
      sources: ["S450", "S458"]
    },
    {
      title: "阶段二：干预点 (第 5 个月)",
      text: "对于'晚获得 AI 组'，在第 5 个月发生结构性变化。一旦接入 AI 系统，其生产力曲线立即脱离原有的缓慢增长路径，出现明显的向上跳跃。",
      sources: ["S460", "S967"]
    },
    {
      title: "阶段三：加速追赶期 (5 个月后)",
      text: "获得 AI 后，该组代理的生产力增长斜率变得极陡，迅速追平甚至超过那些从一开始就有 AI 辅助的资深代理。这证明生产力的飞跃是 AI 介入的直接结果，而非时间推移的自然产物。",
      sources: ["S460", "S461", "S465"]
    }
  ];

  // 坐标转换函数
  function mapX(month) {
    // 0-10 个月映射到 60-740 像素
    return 60 + (month / 10) * 680;
  }

  function mapY(resolutions) {
    // 1-4 次/小时映射到 420-40 像素 (SVG Y 轴向下)
    return 420 - ((resolutions - 1) / 3) * 380;
  }

  // 生成路径数据
  function generatePathData(group, maxMonth) {
    let points = [];

    if (group === 'never') {
      // Never Treated: 缓慢增长，2.0 -> 2.5 (8-10 个月)
      for (let m = 0; m <= maxMonth; m += 0.5) {
        let r = 2.0 + (m / 10) * 0.5; // 线性近似
        if (r > 2.5 && m > 8) r = 2.5; // 饱和
        points.push(`${mapX(m)},${mapY(r)}`);
      }
    } else if (group === 'always') {
      // Always Treated: 快速增长，2.0 -> 2.5 (2 个月) -> 3.0+ (5 个月)
      for (let m = 0; m <= maxMonth; m += 0.5) {
        let r;
        if (m <= 2) {
          r = 2.0 + (m / 2) * 0.5; // 快速上升到 2.5
        } else {
          r = 2.5 + (m - 2) * 0.15; // 继续增长
        }
        if (r > 3.2) r = 3.2; // 上限
        points.push(`${mapX(m)},${mapY(r)}`);
      }
    } else if (group === 'treated5') {
      // Treated 5 mo.: 前 5 个月同 never, 之后快速追赶
      for (let m = 0; m <= maxMonth; m += 0.5) {
        let r;
        if (m <= 5) {
          r = 2.0 + (m / 10) * 0.5; // 同 never
          if (r > 2.25) r = 2.25; // 5 个月时约 2.25
        } else {
          // 从 2.25 开始快速追赶，斜率类似 always
          r = 2.25 + (m - 5) * 0.2;
        }
        if (r > 3.2) r = 3.2;
        points.push(`${mapX(m)},${mapY(r)}`);
      }
    }

    return points.join(' ');
  }

  // 初始化图表
  function initChart() {
    const svg = document.getElementById('experience-curve-svg');
    const pathsGroup = document.getElementById('chart-paths');
    const annotationGroup = document.getElementById('annotation-group');

    // 清除现有路径
    pathsGroup.innerHTML = '';

    // 创建路径元素
    const colors = {
      always: '#E53E3E',
      never: '#2C5282',
      treated5: '#38A169'
    };

    // 绘制完整路径 (10 个月)
    Object.keys(colors).forEach(key => {
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      path.setAttribute('d', `M ${generatePathData(key, 10)}`);
      path.setAttribute('stroke', colors[key]);
      path.setAttribute('fill', 'none');
      path.setAttribute('stroke-width', '3');
      path.setAttribute('class', `curve-${key}`);
      pathsGroup.appendChild(path);
    });

    // 默认显示标注
    annotationGroup.setAttribute('display', 'block');
  }

  // 更新步骤视图
  function updateStep(stepIndex) {
    const step = STEPS[stepIndex];
    const titleEl = document.getElementById('step-title');
    const textEl = document.getElementById('step-text');
    const sourcesEl = document.querySelector('.source-links');
    const indicators = document.querySelectorAll('.indicator');
    const pathsGroup = document.getElementById('chart-paths');
    const annotationGroup = document.getElementById('annotation-group');

    // 更新文本
    titleEl.textContent = step.title;
    textEl.textContent = step.text;

    // 更新来源按钮
    sourcesEl.innerHTML = '';
    step.sources.forEach(sourceId => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'source-btn';
      btn.setAttribute('data-source', sourceId);
      const sourceData = window.paperMindData?.sources?.[sourceId];
      const page = sourceData ? sourceData.page : '?';
      btn.textContent = `原文 · p.${page}`;
      sourcesEl.appendChild(btn);
    });

    // 更新指示器
    indicators.forEach((ind, idx) => {
      ind.classList.toggle('active', idx === stepIndex);
    });

    // 更新图表显示
    pathsGroup.innerHTML = '';
    const colors = {
      always: '#E53E3E',
      never: '#2C5282',
      treated5: '#38A169'
    };

    // 根据步骤显示不同阶段
    let maxMonth = 10;
    let showAnnotation = false;

    if (stepIndex === 0) {
      maxMonth = 5;
      showAnnotation = false;
    } else if (stepIndex === 1) {
      maxMonth = 5;
      showAnnotation = true;
    } else if (stepIndex === 2) {
      maxMonth = 10;
      showAnnotation = true;
    }

    // 重新绘制路径
    Object.keys(colors).forEach(key => {
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      path.setAttribute('d', `M ${generatePathData(key, maxMonth)}`);
      path.setAttribute('stroke', colors[key]);
      path.setAttribute('fill', 'none');
      path.setAttribute('stroke-width', '3');
      // 对于 treated5 组，在步骤 1 和 2 中使用虚线表示预测/追赶部分
      if (key === 'treated5' && stepIndex >= 1) {
        path.setAttribute('stroke-dasharray', '5,5');
      }
      pathsGroup.appendChild(path);
    });

    // 控制标注显示
    annotationGroup.setAttribute('display', showAnnotation ? 'block' : 'none');
  }

  // 事件处理
  function setupEventListeners() {
    let currentStep = 0;
    const totalSteps = STEPS.length;

    const prevBtn = document.getElementById('btn-prev');
    const nextBtn = document.getElementById('btn-next');
    const resetBtn = document.getElementById('reset-btn');
    const indicators = document.querySelectorAll('.indicator');

    prevBtn.addEventListener('click', () => {
      if (currentStep > 0) {
        currentStep--;
        updateStep(currentStep);
      }
    });

    nextBtn.addEventListener('click', () => {
      if (currentStep < totalSteps - 1) {
        currentStep++;
        updateStep(currentStep);
      }
    });

    resetBtn.addEventListener('click', () => {
      currentStep = 0;
      updateStep(currentStep);
      initChart();
    });

    // 键盘导航
    document.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft' && currentStep > 0) {
        currentStep--;
        updateStep(currentStep);
      } else if (e.key === 'ArrowRight' && currentStep < totalSteps - 1) {
        currentStep++;
        updateStep(currentStep);
      }
    });

    // 点击指示器跳转
    indicators.forEach((ind, idx) => {
      ind.addEventListener('click', () => {
        currentStep = idx;
        updateStep(currentStep);
      });
    });

    // 来源按钮事件 (由内核处理)
    document.addEventListener('click', (e) => {
      if (e.target.classList.contains('source-btn')) {
        // 内核将处理 data-source 属性
        console.log('Source requested:', e.target.getAttribute('data-source'));
      }
    });
  }

  // 初始化
  function init() {
    initChart();
    updateStep(0);
    setupEventListeners();
  }

  // 等待 DOM 加载完成
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
